def icon(name='arrow'):
 return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{PATHS[name]}"/></svg>'
def image(key, cls='', eager=False, sizes='(min-width: 900px) 50vw, 100vw'):
 alt=PROJECTS[key][5]
 return f'<img class="{cls}" src="/assets/concepts/{key}-900.webp" srcset="/assets/concepts/{key}-480.webp 480w, /assets/concepts/{key}-900.webp 900w, /assets/concepts/{key}-1400.webp 1400w" sizes="{sizes}" width="1536" height="1024" alt="{alt}" loading="{"eager" if eager else "lazy"}" {"fetchpriority=high" if eager else ""} decoding="async">'
def cta(text='Parlons de votre projet',cls='button',href='#contact'):
 return f'<a class="{cls}" href="{href}">{text}{icon()}</a>'
def kicker(text):return f'<p class="eyebrow">{text}</p>'
def heading(eyebrow,title,text='',extra=''):
 return f'<div class="section-head">{kicker(eyebrow)}<div><h2>{title}</h2>{f"<p>{text}</p>" if text else ""}</div>{extra}</div>'
def project(key, cls='', eager=False):
 p=PROJECTS[key]
 return f'<article class="project {cls}" data-category="{p[2]}"><button class="project-open" data-project="{key}" aria-label="Explorer le concept {p[0]}"><span class="project-image">{image(key,eager=eager)}<span class="concept-tag">Concept créatif</span><span class="project-arrow">{icon("up")}</span></span><span class="project-caption"><span><strong>{p[0]}</strong><span>{p[1]}</span></span><span class="project-no">{list(PROJECTS).index(key)+1:02}</span></span></button></article>'
def proof():
 logos=[('golden-tulip','Golden Tulip'),('maghrebia','Maghrebia'),('delice-danone','Délice Danone'),('rne','Registre National des Entreprises'),('cnci',"Centre National du Cinéma et de l’Image"),('soquibat','Soquibat')]
 return '<section class="proof" id="partenaires"><div class="wrap proof-inner"><p>Des univers différents.<br><strong>Une même confiance.</strong><span>Partenaires de Magic 360</span></p><div class="partner-logos">'+''.join(f'<img src="/assets/partners/clean/{f}.png" alt="{n}" width="180" height="76" loading="lazy">' for f,n in logos)+'</div></div></section>'
def filters():
 return '<div class="filters" role="group" aria-label="Filtrer les concepts">'+''.join(f'<button data-filter="{k}" aria-pressed="{str(i==0).lower()}">{v}</button>' for i,(k,v) in enumerate([('all','Tout voir'),('branding','Branding'),('campagne','Campagne'),('digital','Digital'),('experience','Expérience')]))+'</div><p class="filter-status sr-only" role="status"></p>'
def gallery(keys,cls='',filterable=True):
 return f'<div class="gallery-area">{filters() if filterable else ""}<div class="projects {cls}">'+''.join(project(k) for k in keys)+'</div><p class="concept-note">Explorations visuelles — marques fictives et images générées pour cette présentation. Ces concepts ne sont pas des réalisations clients.</p></div>'
def services(cls='',first=True):
 return f'<div class="services-list {cls}">'+''.join(f'<details class="service" id="{["strategie","branding","digital","production","packaging","events","affichage","b2b","recherche"][i]}" {"open" if i==0 and first else ""}><summary><span class="service-number">{i+1:02}</span>{icon(s[3])}<span>{s[0]}</span><span class="expand">{icon("plus")}</span></summary><div class="service-description"><h3>{s[1]}</h3><p>{s[2]}</p><a href="#contact">Discuter de ce besoin {icon()}</a></div></details>' for i,s in enumerate(SERVICES))+'</div>'
STEPS=[('Écouter','Votre contexte, vos publics, vos objectifs. On commence par comprendre ce qui compte pour vous.'),('Imaginer','Une direction claire, des idées et des supports pensés pour fonctionner ensemble.'),('Réaliser','Du premier concept au déploiement, nous coordonnons la création et la production.')]
def steps(cls=''):
 return f'<div class="steps {cls}">'+''.join(f'<article><span class="step-number">0{i+1}</span><h3>{s[0]}</h3><p>{s[1]}</p></article>' for i,s in enumerate(STEPS))+'</div>'
def faq():
 qs=[('Peut-on vous confier un seul besoin ?',"Oui. Un projet d’identité, une campagne, un événement ou un site peut être abordé séparément. Nous définissons ensemble le périmètre utile."),('Comment démarre un projet ?',"Un premier échange permet de comprendre votre besoin, vos supports, votre calendrier et votre budget. Nous préparons ensuite une proposition adaptée."),('Comment sont définis le budget et les délais ?',"Ils dépendent du périmètre, des livrables et des contraintes de production. Le devis et le calendrier sont précisés avant de lancer le travail."),('Les projets présentés ici sont-ils réels ?',"Les projets Zéra, Horizon, Rencontres, Maison Nūr et Soli sont des concepts fictifs créés pour explorer cette nouvelle présentation du site. Les logos de partenaires proviennent du site existant et ne sont pas associés à ces concepts.")]
