def build():
 for key,name,url in THEMES:
  target=ROOT/url.strip('/')/'index.html'
  target.parent.mkdir(parents=True,exist_ok=True)
  target.write_text(shell(key,name,globals()[key]()),encoding='utf-8')
 print('Built five complete static homepages.')
if __name__=='__main__':build()
